        .graph
        .identity()
        .platform
        .get("@scope/my-lib-linux-x64-gnu")
        .expect("platform entry must exist");

    assert_eq!(
        crate::napi::role_to_triple(role).as_deref(),
        Some("x86_64-unknown-linux-gnu"),
        "expected a resolvable triple, got role: {role:?}"
    );
}

